import {PLAYER_NAMES} from './table-seats.js?v=10c';
export function evaluate5(hand){const ranks=hand.map(c=>c.rank).sort((a,b)=>b-a),counts={};ranks.forEach(r=>counts[r]=(counts[r]||0)+1);const groups=Object.entries(counts).map(([r,n])=>[n,+r]).sort((a,b)=>b[0]-a[0]||b[1]-a[1]);const flush=hand.every(c=>c.suit===hand[0].suit);const unique=[...new Set(ranks)];let straight=unique.length===5&&unique[0]-unique[4]===4?unique[0]:unique.join(',')==='14,5,4,3,2'?5:0;let category=0,name='High card',tie=ranks;if(straight&&flush){category=8;name='Straight flush';tie=[straight];}else if(groups[0][0]===4){category=7;name='Four of a kind';tie=groups.map(g=>g[1]);}else if(groups[0][0]===3&&groups[1][0]===2){category=6;name='Full house';tie=groups.map(g=>g[1]);}else if(flush){category=5;name='Flush';}else if(straight){category=4;name='Straight';tie=[straight];}else if(groups[0][0]===3){category=3;name='Three of a kind';tie=groups.map(g=>g[1]);}else if(groups[0][0]===2&&groups[1][0]===2){category=2;name='Two pairs';tie=groups.map(g=>g[1]);}else if(groups[0][0]===2){category=1;name='One pair';tie=groups.map(g=>g[1]);}const vector=[category,...tie];while(vector.length<6)vector.push(0);return {name,value:vector.reduce((a,b)=>a*15+b,0)};}
export function evaluate7(cards) {
  let best=null;
  for(let a=0;a<cards.length-4;a++)for(let b=a+1;b<cards.length-3;b++)for(let c=b+1;c<cards.length-2;c++)for(let d=c+1;d<cards.length-1;d++)for(let e=d+1;e<cards.length;e++){
    const five=[cards[a],cards[b],cards[c],cards[d],cards[e]], score=evaluate5(five);
    if(!best||score.value>best.value)best={...score,cards:five};
  }
  return best;
}
export function deckOfCards(random=Math.random){const d=[];for(let s=0;s<4;s++)for(let r=2;r<=14;r++)d.push({rank:r,suit:s});for(let i=51;i>0;i--){const j=Math.floor(random()*(i+1));[d[i],d[j]]=[d[j],d[i]];}return d;}
export class Holdem {
  constructor(random=Math.random,names=PLAYER_NAMES){this.random=random;this.players=names.map(name=>({name,stack:300,cards:[],folded:false,bet:0,total:0,last:''}));this.dealer=-1;this.hand=0;this.stage='waiting';this.board=[];this.log=[];this.winners=[];this.awards=[];this.pot=0;this.actor=-1;}
  message(s){this.log.push(s);if(this.log.length>15)this.log.shift();}
  nextIndex(i,predicate=p=>p.stack>0){for(let n=1;n<=this.players.length;n++){const j=(i+n)%this.players.length;if(predicate(this.players[j]))return j;}return -1;}
  pay(i,amount){const p=this.players[i],n=Math.min(p.stack,amount);p.stack-=n;p.bet+=n;p.total+=n;this.pot+=n;return n;}
  start(){if(this.players.filter(p=>p.stack>0).length<2){this.stage='finished';return false;}this.hand++;this.dealer=this.nextIndex(this.dealer);this.deck=deckOfCards(this.random);this.board=[];this.pot=0;this.winners=[];this.awards=[];this.result='';this.log=[];this.stage='preflop';this.raises=1;this.currentBet=10;this.players.forEach(p=>Object.assign(p,{cards:p.stack>0?[this.deck.pop(),this.deck.pop()]:[],folded:p.stack===0,bet:0,total:0,last:p.stack===0?'Sitting out':''}));const active=this.players.filter(p=>!p.folded).length;const sb=active===2?this.dealer:this.nextIndex(this.dealer);const bb=this.nextIndex(sb);this.pay(sb,5);this.pay(bb,10);this.players[sb].last='Small blind 5';this.players[bb].last='Big blind 10';this.message(`Hand ${this.hand}. Blinds 5 / 10. ${this.players[this.dealer].name} deals.`);this.pending=new Set(this.players.map((p,i)=>!p.folded&&p.stack>0?i:-1).filter(i=>i>=0));this.actor=this.nextIndex(bb,(p)=>this.pending.has(this.players.indexOf(p)));if(!this.pending.size||(this.pending.size===1&&this.legal(this.actor).due===0))this.advance();return true;}
  unit(){return ['turn','river'].includes(this.stage)?20:10;}
  legal(i=this.actor){if(i<0)return{};const p=this.players[i];const due=Math.max(0,this.currentBet-p.bet);return{due,canCheck:due===0,call:Math.min(due,p.stack),canRaise:this.raises<4&&p.stack>=due+this.unit(),raiseTo:this.currentBet+this.unit()};}
  act(type){const i=this.actor;if(i<0||['showdown','finished','waiting'].includes(this.stage))return false;const p=this.players[i],l=this.legal();if(type==='check'&&!l.canCheck||type==='raise'&&!l.canRaise)return false;
    if(type==='fold'){p.folded=true;p.last='Fold';this.message(`${p.name} ${p.name==='You'?'fold':'folds'}.`);}
    else if(type==='raise'){this.pay(i,l.raiseTo-p.bet);this.currentBet=l.raiseTo;this.raises++;p.last=`${l.due?'Raise':'Bet'} ${this.currentBet}`;this.message(`${p.name} ${l.due?(p.name==='You'?'raise to':'raises to'):(p.name==='You'?'bet':'bets')} ${this.currentBet}.`);this.pending=new Set(this.players.map((q,j)=>j!==i&&!q.folded&&q.stack>0?j:-1).filter(j=>j>=0));}
    else if(type==='call'||type==='check'){const paid=this.pay(i,l.due);p.last=paid?`${p.stack===0?'All-in':'Call'} ${paid}`:'Check';this.message(`${p.name}: ${p.last.toLowerCase()}.`);}else return false;
    this.pending.delete(i);for(const j of this.pending)if(this.players[j].folded||!this.players[j].stack)this.pending.delete(j);
    const live=this.players.map((q,j)=>!q.folded?j:-1).filter(j=>j>=0);
    if(live.length===1){this.players[live[0]].stack+=this.pot;this.winners=live;this.awards=[{seat:live[0],amount:this.pot}];this.result=`${this.players[live[0]].name} wins ${this.pot} chips. Everyone else folded.`;this.stage='showdown';this.actor=-1;return true;}
    if(!this.pending.size)this.advance();else this.actor=this.nextIndex(i,p=>this.pending.has(this.players.indexOf(p)));return true;
  }
  advance(){const remaining=this.players.filter(p=>!p.folded&&p.stack>0);if(this.stage==='river'||remaining.length<2){while(this.board.length<5)this.board.push(this.deck.pop());this.settle();return;}this.deck.pop();if(this.stage==='preflop'){this.board.push(this.deck.pop(),this.deck.pop(),this.deck.pop());this.stage='flop';}else {this.board.push(this.deck.pop());this.stage=this.stage==='flop'?'turn':'river';}this.players.forEach(p=>{p.bet=0;p.last=p.folded?'Folded':p.stack===0?'All-in':'';});this.currentBet=0;this.raises=0;this.pending=new Set(this.players.map((p,i)=>!p.folded&&p.stack>0?i:-1).filter(i=>i>=0));this.actor=this.nextIndex(this.dealer,p=>this.pending.has(this.players.indexOf(p)));this.message(`${this.stage[0].toUpperCase()+this.stage.slice(1)}. New betting round.`);}
  settle(){this.stage='showdown';this.actor=-1;const levels=[...new Set(this.players.map(p=>p.total).filter(Boolean))].sort((a,b)=>a-b);let previous=0;const won=new Map();for(const level of levels){const contributors=this.players.map((p,i)=>p.total>=level?i:-1).filter(i=>i>=0);const amount=(level-previous)*contributors.length;previous=level;const eligible=contributors.filter(i=>!this.players[i].folded);if(!eligible.length)continue;const scores=eligible.map(i=>[i,evaluate7([...this.players[i].cards,...this.board]).value]);const max=Math.max(...scores.map(s=>s[1]));const winners=scores.filter(s=>s[1]===max).map(s=>s[0]);winners.sort((a,b)=>(a-this.dealer-1+this.players.length)%this.players.length-(b-this.dealer-1+this.players.length)%this.players.length);winners.forEach((i,k)=>{const chips=Math.floor(amount/winners.length)+(k<amount%winners.length?1:0);this.players[i].stack+=chips;won.set(i,(won.get(i)||0)+chips);});}this.winners=[...won.keys()];this.awards=[...won].map(([seat,amount])=>({seat,amount}));this.result=[...won].map(([i,n])=>`${this.players[i].name}: ${evaluate7([...this.players[i].cards,...this.board]).name} · +${n} chips`).join(' / ');this.message(this.result);}
  bot(){if(this.actor<=0)return false;const p=this.players[this.actor],l=this.legal();const ranks=p.cards.map(c=>c.rank);const pair=ranks[0]===ranks[1];let strength=pair?.7:Math.max(...ranks)>=12?.55:.3;if(this.board.length){const result=evaluate7([...p.cards,...this.board]);strength=Math.min(.95,.2+Math.floor(result.value/15**5)*.18);}const r=this.random();if(l.due&&strength<.4&&r<.35)return this.act('fold');if(l.canRaise&&r<strength*.3)return this.act('raise');return this.act(l.canCheck?'check':'call');}
}
